#!/usr/bin/env python3
"""Regenerate smurfsniper/_modules.py from the package tree."""

from __future__ import annotations

import pkgutil
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent


def render(names: list[str]) -> str:
    body = "".join(f'    "{n}",\n' for n in names)
    return (
        '"""Static module list for frozen builds. Generated by scripts/gen_modules.py."""\n\n'
        f"MODULES: tuple[str, ...] = (\n{body})\n"
    )


def main() -> int:
    sys.path.insert(0, str(ROOT))
    import smurfsniper

    names = sorted(m.name for m in pkgutil.walk_packages(smurfsniper.__path__, "smurfsniper."))
    names = [n for n in names if n != "smurfsniper._modules"]
    (ROOT / "smurfsniper" / "_modules.py").write_text(render(names), encoding="utf-8")
    return 0


if __name__ == "__main__":
    sys.exit(main())
